mapper.select:

where t.project_id = #{projectId}
  and t.pr_number = #{prNumber}
  and t.task_status = 'SUCCESS'
order by t.finished_time desc, t.task_id desc
limit 1


where 1 = 1

    and t.project_id = #{projectId}


    and t.pr_number = #{prNumber}


    and t.task_status = #{taskStatus}


    and t.task_status in ('PENDING', 'RUNNING', 'FAILED')


    and t.trigger_type = #{triggerType}


    and date_format(t.create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


    and date_format(t.create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')

${params.dataScope}
order by t.task_id desc


where t.task_status in ('SUCCESS', 'FAILED')

    and t.project_id = #{projectId}


    and t.pr_number = #{prNumber}


    and t.pr_author like concat('%', #{prAuthor}, '%')


    and t.task_status = 'FAILED'


    and t.task_status = 'SUCCESS' and t.review_conclusion = #{reviewConclusion}


    and date_format(ifnull(t.finished_time, t.create_time),'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


    and date_format(ifnull(t.finished_time, t.create_time),'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')

${params.dataScope}
order by ifnull(t.finished_time, t.create_time) desc, t.task_id desc

select count(1)
from review_task t
inner join review_project p on p.project_id = t.project_id
left join sys_business_system bs on bs.system_id = p.business_system_id
inner join sys_dept d on d.dept_id = p.dept_id
inner join sys_user owner on owner.user_id = p.owner_user_id
where 1 = 1

    and t.project_id = #{projectId}


    and t.pr_number = #{prNumber}


    and t.task_status = #{taskStatus}


    and t.task_status in ('PENDING', 'RUNNING', 'FAILED')


    and t.trigger_type = #{triggerType}


    and date_format(t.create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


    and date_format(t.create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')

${params.dataScope}

select count(1) from review_task t inner join review_project p on p.project_id = t.project_id left join sys_business_system bs on bs.system_id = p.business_system_id inner join sys_dept d on d.dept_id = p.dept_id inner join sys_user owner on owner.user_id = p.owner_user_id where t.task_status in ('SUCCESS', 'FAILED')
and t.project_id = #{projectId}
and t.pr_number = #{prNumber}
and t.pr_author like concat('%', #{prAuthor}, '%')
and t.task_status = 'FAILED'
and t.task_status = 'SUCCESS' and t.review_conclusion = #{reviewConclusion}
and date_format(ifnull(t.finished_time, t.create_time),'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')
and date_format(ifnull(t.finished_time, t.create_time),'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')
${params.dataScope}
